  "cpm.pass.tex": "\\begin{aligned} \\mathit{ES}_j &= \\max_{i \\in P(j)} \\mathit{EF}_i, & \\mathit{EF}_j &= \\mathit{ES}_j + d_j \\\\ \\mathit{LF}_i &= \\min_{j \\in S(i)} \\mathit{LS}_j, & \\mathit{LS}_i &= \\mathit{LF}_i - d_i \\\\ s_i &= \\mathit{LS}_i - \\mathit{ES}_i & & \\text{(holgura)} \\end{aligned}",
  "cpm.pass.formula": "ES_j = máximo de EF_i sobre las predecesoras i,   EF_j = ES_j + d_j\nLF_i = mínimo de LS_j sobre las sucesoras j,     LS_i = LF_i − d_i\ns_i = LS_i − ES_i   (holgura)",
  "cpm.pass.why": "P(j) son las predecesoras de j y S(i) las sucesoras de i. La duración del proyecto es el mayor EF, y las actividades con holgura cero forman la ruta crítica: el camino más largo de la red.",
  "cpm.lp.head": "La misma respuesta como programa lineal",
